#include <bits/stdc++.h>
using namespace std;
typedef pair<int, int> pii;
char maze1[15][15], maze2[15][15];
int move[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
int node_idx[65][15][15];
int flow_cap[15][15];
int node_id = 1;

struct Edge {
  int from, to;
  long long capacity, currentFlow;
  Edge() {}
  Edge(int u, int v, long long cap): from(u), to(v), capacity(cap), currentFlow(0) {}
};

struct FlowNetwork {
  int totalNodes;
  vector<Edge> edges;
  vector<vector<int>> adj;
  vector<int> level, ptr;

  FlowNetwork(int N): totalNodes(N), edges(), adj(N), level(N), ptr(N) {}

  void addEdge(int u, int v, long long cap) {
    if (u != v) {
      edges.emplace_back(Edge(u, v, cap));
      adj[u].push_back(edges.size() - 1);
      edges.emplace_back(Edge(v, u, 0));
      adj[v].push_back(edges.size() - 1);
    }
  }

  bool buildLevelGraph(int S, int T) {
    queue<int> q({S});
    fill(level.begin(), level.end(), totalNodes + 1);
    level[S] = 0;
    while (!q.empty()) {
      int u = q.front(); q.pop();
      if (u == T) break;
      for (int e_idx: adj[u]) {
        Edge &e = edges[e_idx];
        if (e.currentFlow < e.capacity && level[e.v] > level[e.u] + 1) {
          level[e.v] = level[e.u] + 1;
          q.push(e.v);
        }
      }
    }
    return level[T] != totalNodes + 1;
  }

  long long sendFlow(int u, int T, long long flow = -1) {
    if (u == T || flow == 0) return flow;
    for (int &i = ptr[u]; i < (int)adj[u].size(); ++i) {
      Edge &e = edges[adj[u][i]];
      Edge &oe = edges[adj[u][i]^1];
      if (level[e.v] == level[e.u] + 1) {
        long long amt = e.capacity - e.currentFlow;
        if (flow != -1 && amt > flow) amt = flow;
        long long pushed = sendFlow(e.v, T, amt);
        if (pushed > 0) {
          e.currentFlow += pushed;
          oe.currentFlow -= pushed;
          return pushed;
        }
      }
    }
    return 0;
  }

  long long maxFlow(int S, int T) {
    long long total = 0;
    while (buildLevelGraph(S, T)) {
      fill(ptr.begin(), ptr.end(), 0);
      while (long long flow = sendFlow(S, T))
        total += flow;
    }
    return total;
  }
};

int main() {
  memset(flow_cap, -1, sizeof(flow_cap));
  int n, t;
  scanf("%d%d", &n, &t);
  for (int i=1; i<=n; i++) {
    scanf("%s", maze1[i]+1);
  }
  for (int i=0; i<=t+1; i++) {
    for (int j=1; j<=n; j++) {
      for (int k=1; k<=n; k++) {
        node_idx[i][j][k] = node_id++;
      }
    }
  }
  node_id++;
  for (int i=1; i<=n; i++) {
    scanf("%s", maze2[i]+1);
  }
  queue<pii> q;
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (maze1[i][j] == 'Z') {
        q.push({i, j});
        flow_cap[i][j] = 0;
      }
    }
  }
  while (!q.empty()) {
    int y = q.front().first, x = q.front().second;
    q.pop();
    for (int i=0; i<4; i++) {
      int ny = y + move[i][0], nx = x + move[i][1];
      if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && maze1[ny][nx] != 'Y' && flow_cap[ny][nx] == -1) {
        flow_cap[ny][nx] = flow_cap[y][x] + 1;
        q.push({ny, nx});
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (flow_cap[i][j] == -1) flow_cap[i][j] = 1e9;
      if (flow_cap[i][j] > t) flow_cap[i][j] = 1e9;
    }
  }
  int s = 0, t_node = node_id - 1;
  FlowNetwork network(node_id);
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (maze1[i][j] >= '1' && maze1[i][j] <= '9') {
        network.addEdge(s, node_idx[0][i][j], maze1[i][j]-'0');
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (maze1[i][j] == 'Y' || maze1[i][j] == 'Z') continue;
      for (int k=0; k<4; k++) {
        int ny = i + move[k][0], nx = j + move[k][1];
        if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && maze1[ny][nx] != 'Y' && maze1[ny][nx] != 'Z') {
          for (int x=0; x<t; x++) {
            if (flow_cap[ny][nx] >= x+1 && flow_cap[i][j] > x) {
              network.addEdge(node_idx[x][i][j], node_idx[x+1][ny][nx], 1000);
            }
          }
        }
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (maze1[i][j] == 'Y' || maze1[i][j] == 'Z') continue;
      for (int x=0; x<=t; x++) {
        if (maze2[i][j] >= '1' && maze2[i][j] <= '9') {
          network.addEdge(node_idx[x][i][j], node_idx[t+1][i][j], maze2[i][j]-'0');
        }
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (maze1[i][j] == 'Y' || maze1[i][j] == 'Z') continue;
      if (maze2[i][j] >= '1' && maze2[i][j] <= '9') {
        network.addEdge(node_idx[t+1][i][j], t_node, maze2[i][j]-'0');
      }
    }
  }
  printf("%lld\n", network.maxFlow(s, t_node));
}
